sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    var pep;
    var sanc;
    var adv;
    var query = '';
    if (current.kyc_case.entity != '') {
        pep = current.kyc_case.entity.pep;
        sanc = current.kyc_case.entity.sanctions;
        adv = current.kyc_case.entity.adverse_news_screening;
        query = "entity.email_id" + current.kyc_case.entity.email_id;
    } else {
        pep = current.kyc_case.individual.pep;
        sanc = current.kyc_case.individual.sanctions;
        adv = current.kyc_case.individual.adverse_news_screening;
        query = "individual.email" + current.kyc_case.individual.email;
    }
    //var assignUser, caseState;

    // Condition 1: If any YES → Maker
    if (pep == 'yes' || sanc == 'yes' || adv == 'yes') {
        caseState = '150';

        // Condition 2: If all NO → Checker
    } else if (pep == 'no' && sanc == 'no' && adv == 'no') {
        //assignUser = checkerUser;
        caseState = '320';

        // Condition 3: Any empty (or mix of NO + empty) → Do nothing
    } else {
        return;
    }
    var caseGR = new GlideRecord('x_vuram_financia_0_fcc_kyc_cases');
    caseGR.addEnocdedQuery(query);
    caseGR.addQuery('case_type', 'periodic_kyc_case');
    caseGR.addQuery('state', 'NOT IN', '300,350,400,450');
    caseGR.query();
    if (caseGR.next()) {
        if (gs.nil(caseGR.assigned_to)) { // Only update if unassigned
            caseGR.state = caseState;
            //caseGR.assigned_to = assignUser;
            caseGR.update();
            if (caseState == '150')
                current.assigned_to = caseGR.assigned_to;
            else
                current.state = '4';

        }
    }




})(current, previous);
